/**
 * Fluent level builder for a single hole. Every method maps onto the plain
 * descriptors consumed by the renderer, physics and obstacle runtime, so course
 * data stays serializable while authoring stays readable.
 */
export class HoleBuilder {
  private readonly surfaces: SurfaceDescriptor[] = [];
  private readonly obstacles: ObstacleDescriptor[] = [];
  private readonly zones: ZoneDescriptor[] = [];
  private readonly forceObstacles: ForceObstacleConfig[] = [];
  private readonly usedIds = new Set<string>();
  private counter = 0;
  private par: number;
  private spawn: Vec3 | null;
  private cup: Hole['cup'] | null;
  private bounds: Hole['bounds'] | null;

  constructor(private readonly options: HoleBuilderOptions) {
    this.par = options.par;
    this.spawn = options.spawn ? clone(options.spawn) : null;
    this.cup = options.cup ? toCup(options.cup) : null;
    this.bounds = options.bounds
      ? { min: clone(options.bounds.min), max: clone(options.bounds.max) }
      : null;
  }

  setSpawn(position: Vec3): this {
    this.spawn = clone(position);
    return this;
  }

  setPar(par: number): this {
    this.par = par;
    return this;
  }

  setBounds(min: Vec3, max: Vec3): this {
    this.bounds = { min: clone(min), max: clone(max) };
    return this;
  }

  /** Places the cup of this hole. */
  addHole(cup: CupOptions): this {
    this.cup = toCup(cup);
    return this;
  }

  addFloor(options: SurfaceOptions): this {
    return this.pushSurface('box', 'floor', options);
  }

  addRamp(options: SurfaceOptions): this {
    return this.pushSurface('ramp', 'ramp', options);
  }

  /** Approximates a banked curve with box segments laid along an arc. */
  addCurve(options: CurveOptions): this {
    if (!(options.radius > 0)) throw new Error(this.message('curve radius must be positive'));
    if (!(options.width > 0)) throw new Error(this.message('curve width must be positive'));
    if (!options.sweepAngle) throw new Error(this.message('curve sweepAngle must not be zero'));

    const segments = Math.max(1, Math.round(options.segments ?? DEFAULT_CURVE_SEGMENTS));
    const baseId = options.id ?? this.nextId('curve');
    const step = options.sweepAngle / segments;
    const thickness = options.thickness ?? DEFAULT_THICKNESS;
    const length = Math.abs(options.radius * step) * CURVE_OVERLAP;

    for (let index = 0; index < segments; index += 1) {
      const angle = options.startAngle + step * (index + 0.5);
      this.addFloor({
        id: `${baseId}-${index + 1}`,
        position: {
          x: options.center.x + Math.cos(angle) * options.radius,
          y: options.center.y,
          z: options.center.z + Math.sin(angle) * options.radius,
        },
        size: { x: options.width, y: thickness, z: length },
        material: options.material ?? 'green',
        yaw: -angle,
        ...(options.friction !== undefined ? { friction: options.friction } : {}),
      });
    }
    return this;
  }

  addWall(options: WallOptions): this {
    return this.pushObstacle('wall', {
      id: options.id,
      type: 'wall',
      transform: { position: clone(options.position) },
      size: clone(options.size),
      ...(options.restitution !== undefined ? { restitution: options.restitution } : {}),
    });
  }

  addBumper(options: BumperOptions): this {
    return this.pushObstacle('bumper', {
      id: options.id,
      type: 'bumper',
      transform: { position: clone(options.position) },
      size: options.size ? clone(options.size) : { x: 1, y: 1, z: 1 },
      restitution: options.restitution ?? 1.2,
    });
  }

  addSpinner(options: SpinnerOptions): this {
    return this.pushObstacle('spinner', {
      id: options.id,
      type: 'spinner',
      transform: { position: clone(options.position) },
      size: options.size ? clone(options.size) : { x: 5, y: 0.4, z: 0.5 },
      motion: {
        kind: 'rotate',
        axis: options.axis ? clone(options.axis) : { x: 0, y: 1, z: 0 },
        speed: options.speed ?? 1.5,
        ...(options.phase !== undefined ? { phase: options.phase } : {}),
      },
    });
  }

  addMovingPlatform(options: MovingPlatformOptions): this {
    return this.pushObstacle('platform', {
      id: options.id,
      type: 'platform',
      transform: { position: clone(options.position) },
      size: options.size ? clone(options.size) : { x: 2.5, y: 0.35, z: 2.5 },
      motion: {
        kind: 'translate',
        axis: options.axis ? clone(options.axis) : { x: 1, y: 0, z: 0 },
        speed: options.speed ?? 1,
        distance: options.distance ?? 2,
        ...(options.phase !== undefined ? { phase: options.phase } : {}),
      },
    });
  }

  /** Escape hatch for descriptors without a dedicated helper (gates, pillars). */
  addObstacle(obstacle: ObstacleInput): this {
    return this.pushObstacle(obstacle.type, obstacle);
  }
EOF
